/*
 * Keeping in mind there are 86400 seconds per day, write a program that calculates how 
many seconds there are in a week if a week is 7 days.  
 */
package Assignment1;

import java.util.*;

public class HowManySec {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Scanner s = new Scanner(System.in);
		long a = 86400;
		System.out.print(a * 7);
	}

}
